-- Nouvel article du blog : « Existe-t-il une alternative aux formations Instagram en ligne ? »
--
-- Les articles vivent dans la table Supabase `articles`, pas dans le repo :
-- le code ne fait que les lire. Cette migration est donc la SEULE façon de
-- publier le texte. Les 5 images sont, elles, commitées dans public/blog/.
--
-- Idempotent : rejouer la migration met l'article à jour au lieu d'échouer.

INSERT INTO public.articles
  (slug, title, excerpt, cover_url, cover_alt, author, published_at,
   content, seo_title, seo_description)
VALUES (
  'alternative-formation-instagram',
  'Existe-t-il une alternative aux formations Instagram en ligne ?',
  'Oui, il en existe six, de la communauté à 39 € par mois à la délégation en agence. Ce que chacune coûte vraiment en 2026, et comment choisir.',
  '/blog/alternative-formation-instagram-cover.webp',
  'Une femme travaille sur son ordinateur portable près d''une fenêtre, assise sur un rebord clair',
  'Laetitia Mattioli',
  '2026-08-05'::date,
  '[{"type": "quote", "text": "Oui, il en existe six. Et le prix n''est pas le bon critère pour choisir."}, {"type": "p", "text": "Oui. Il existe au moins six alternatives aux formations Instagram en ligne, de la communauté à quelques dizaines d''euros par mois jusqu''à la délégation complète en agence. Laquelle te convient ne dépend pas de ton budget, mais d''une seule question : **est-ce que ce qui te manque, c''est le savoir, ou le temps et quelqu''un à côté de toi ?**"}, {"type": "p", "text": "Cet article donne les six formats, ce que chacun coûte vraiment en 2026, à qui il s''adresse, et comment repérer un accompagnement qui te laissera seule malgré ce qu''il promet. Je suis Laetitia Mattioli, fondatrice de Nowadays Agency, une [agence de communication engagée et responsable](/demarche-ethique) installée à Joigny, dans l''Yonne, et j''enseigne Instagram, le SEO et Pinterest à l''ENSAD-PSL, à Sup de Pub, à l''ISCPA, à Cesacom, à BDMMA et à l''EPSAA. Donc non, ce n''est pas un article contre les formations. C''est un article sur ce qui se passe **après**."}, {"type": "h2", "text": "Pourquoi une bonne formation Instagram ne suffit pas ?"}, {"type": "p", "text": "En dix ans et plus de 150 projets accompagnés, voilà ce que je vois arriver le plus souvent."}, {"type": "img", "src": "/blog/alternative-formation-instagram-0.webp", "alt": "Une femme au téléphone devant son ordinateur portable : savoir quoi publier et avoir le temps de le faire sont deux choses différentes"}, {"type": "p", "text": "Les femmes qui me contactent après une formation ne l''ont pas finie. Pas parce que la formation était mauvaise, pas parce qu''elles ont manqué de sérieux. Elles se sont arrêtées au module 4 sur 9, ou au module 7, avec les vidéos toujours accessibles à vie et la culpabilité qui va avec."}, {"type": "p", "text": "Et ce qu''elles ressentent en arrivant, ce n''est pas de l''ignorance. C''est de la frustration."}, {"type": "p", "text": "La frustration, c''est de **savoir**. De savoir ce qu''est un hook, à quoi sert un carrousel, pourquoi il faut un pilier de contenu qui parle du problème et un autre qui parle de toi. De pouvoir l''expliquer à une copine autour d''un café. Et de rouvrir Instagram le lundi matin sans rien publier, parce que savoir quoi faire et avoir le temps de le faire sont deux choses différentes."}, {"type": "p", "text": "Parce que c''est ça, le vrai sujet : **le temps**. Une formation te donne une méthode et te laisse l''appliquer. Or appliquer, c''est long. Écrire, choisir les visuels, tourner, monter, programmer, répondre aux commentaires, recommencer la semaine suivante, pendant que tu fais tourner ton business par ailleurs. Une formation qui promet de « te faire gagner du temps » te donne en réalité du travail en plus, au moins les premiers mois."}, {"type": "p", "text": "(Et je m''inclus dedans : j''ai des cours en ligne, ils sont bien faits, et je sais très bien que toutes celles qui les achètent ne les termineront pas.)"}, {"type": "p", "text": "Le deuxième manque est plus difficile à dire à voix haute : **il faut quelqu''un**. Pas une communauté Facebook de 800 personnes. Pas un groupe Slack où tu poses une question à laquelle trois inconnues répondent trois choses contradictoires. Quelqu''un qui regarde ton compte à toi, ton offre à toi, et qui te dit quoi faire lundi. En individuel."}, {"type": "p", "text": "C''est la phrase qui revient le plus souvent dans mes appels découverte, presque mot pour mot :"}, {"type": "quote", "text": "« j''aimerais qu''on le fasse avec moi »."}, {"type": "h2", "text": "Quelles sont les alternatives, concrètement ?"}, {"type": "p", "text": "Six formats existent. Je les classe par ce qu''ils te demandent, pas par ce qu''ils coûtent."}, {"type": "img", "src": "/blog/alternative-formation-instagram-1.webp", "alt": "Un ordinateur portable, un carnet et un café posés sur un bureau clair : six façons de se faire accompagner"}, {"type": "table", "caption": "Les six alternatives aux formations Instagram, et leur budget de référence en 2026", "headers": ["Format", "Ce que ça t''apporte", "Ce que ça te demande", "Budget 2026"], "rows": [["Formation en autonomie", "Une méthode complète, à ton rythme", "Tout appliquer seule", "25 à 200 €"], ["Formation courte ou certifiante", "Un cadre, des dates, un groupe", "Y aller, puis appliquer seule", "500 à 3 000 €"], ["Communauté ou abonnement", "Ne plus être seule, des réponses régulières", "Poser tes questions, trier les réponses", "Quelques dizaines d''euros par mois. [L''Assistant Com''](https://nowadays-assistant.fr) Premium de Nowadays est à 39 € par mois"], ["Audit", "Un diagnostic écrit de ce qui cloche", "Corriger toi-même ensuite", "1 000 à 5 000 €"], ["Faire-avec (binôme, mentorat individuel)", "Une stratégie construite pour toi, puis quelqu''un à côté pendant que tu appliques", "Être présente aux rendez-vous", "1 650 à 2 980 € pour trois à six mois"], ["Délégation complète", "Tu ne t''en occupes plus", "Valider, et payer", "300 à 4 500 € par mois en freelance ; [1 500 à 8 000 € par mois en agence](/cooperative-asso) pour une PME"]]}, {"type": "p", "text": "Trois précisions, parce que ces fourchettes cachent des pièges."}, {"type": "p", "text": "**L''audit à 1 000 € minimum, c''est un tarif d''agence pour des entreprises structurées.** Pour une solopreneur·e, un audit seul est rarement le bon achat : tu ressors avec un document de vingt pages qui te dit tout ce qui ne va pas, et tu es exactement au même point qu''avant, sauf que maintenant tu sais. Un audit vaut le coup quand il est la première étape d''un accompagnement, pas quand il est le produit."}, {"type": "p", "text": "**Le mentorat individuel est le format qui a le plus grandi.** [LiveMentor](https://www.livementor.com/), la référence française du secteur, affiche entre 1 650 et 1 980 € pour trois mois de formation avec mentorat individuel, et entre 2 750 et 2 980 € pour la formule intensive sur six mois. Ces montants sont souvent finançables par le CPF, France Travail ou un OPCO, ce qui change complètement le calcul si tu y as droit."}, {"type": "p", "text": "**La délégation coûte moins cher qu''on ne le croit en bas de fourchette, et beaucoup plus haut qu''on ne l''imagine.** Le TJM médian d''un community manager freelance en France est de 320 € HT en 2026 selon les données [Malt](https://www.malt.fr/t/barometre-tarifs/communication/community-manager). Un forfait « présence essentielle » démarre à 300 € HT par mois, mais à ce niveau tu achètes de la publication, pas de la stratégie."}, {"type": "h2", "text": "Comment reconnaître un accompagnement qui fait vraiment avec toi ?"}, {"type": "img", "src": "/blog/alternative-formation-instagram-2.webp", "alt": "Deux personnes assises côte à côte, chacune devant son ordinateur : ce que veut dire travailler à quatre mains"}, {"type": "p", "text": "C''est là que se joue la vraie différence, et c''est là que le vocabulaire commercial est le plus flou. Beaucoup de programmes vendus comme de l''« accompagnement » sont des formations avec un appel de groupe par mois. Ce n''est pas malhonnête, mais ce n''est pas la même chose. Les mêmes réflexes servent d''ailleurs à [choisir une agence de communication](/blog/agence-communication-engagee) : regarder ce qui est fait, pas ce qui est promis."}, {"type": "p", "text": "Quatre questions à poser avant de signer. Elles se posent en appel découverte, elles prennent trois minutes, et les réponses sont très parlantes."}, {"type": "h3", "text": "1. Qui écrit le premier jet ?"}, {"type": "p", "text": "Si la réponse est « toi, et je corrige », c''est de la formation avec relecture. Si c''est « moi, et tu valides », c''est du faire-avec. Les deux sont légitimes. Il faut juste savoir lequel tu achètes."}, {"type": "h3", "text": "2. Combien de temps en individuel par mois, et sous quelle forme ?"}, {"type": "p", "text": "Un chiffre, pas un adjectif. « Un suivi personnalisé » ne veut rien dire. « Deux heures en visio par mois, plus WhatsApp les jours ouvrés avec réponse sous 24 à 48 heures », ça veut dire quelque chose."}, {"type": "h3", "text": "3. Qu''est-ce que je fais entre deux rendez-vous ?"}, {"type": "p", "text": "Si la réponse ressemble à une liste de devoirs, tu vas te retrouver exactement là où t''a laissée ta dernière formation. Le signal d''alarme, c''est le programme vendu comme de la délégation dont le contenu réel consiste à te donner du travail."}, {"type": "h3", "text": "4. Qu''est-ce qui reste à moi à la fin ?"}, {"type": "p", "text": "Une stratégie écrite, une bibliothèque de contenus, des gabarits réutilisables ? Ou seulement des replays de visio ? Un bon accompagnement se juge à ce qu''il te laisse quand il s''arrête."}, {"type": "p", "text": "Un cinquième signal, plus discret : demande à voir un livrable réel, anonymisé. Une agence ou une indépendante qui fait vraiment pour toi en a sous la main — les nôtres sont dans [nos études de cas](/etudes-de-cas-pro). Celle qui n''en a pas te vendra du conseil."}, {"type": "h2", "text": "Combien ça coûte, un accompagnement en communication ?"}, {"type": "p", "text": "Pour une solopreneur·e, la zone réaliste se situe entre 1 500 et 3 000 € pour un accompagnement de plusieurs mois qui inclut du temps individuel. En dessous, tu achètes du contenu pédagogique. Au-dessus, tu entres dans la délégation."}, {"type": "p", "text": "Chez Nowadays, ce format s''appelle [Ta Binôme de Com''](/accompagnement-communication) : 350 € par mois pendant six mois. Un paiement étalé, pas un abonnement : le gros du travail est fait les premiers mois. La phase 1 est faite **pour** toi (kick-off, branding, plan de communication sur six mois) ; la phase 2 est faite **avec** toi (une visio de deux heures par mois, WhatsApp les jours ouvrés, validation des livrables). Ça te situe entre la formation avec mentorat et la délégation."}, {"type": "p", "text": "Je le mets à côté des autres plutôt que de le vendre isolément, parce que la comparaison est plus utile que l''argumentaire. Si tu as accès au CPF, une formation certifiante avec mentorat te coûtera moins cher de ta poche. Si ton problème est que tu ne veux plus jamais y toucher, c''est [la délégation](/cooperative-asso) qu''il te faut, et son prix commence là où le mien s''arrête."}, {"type": "h2", "text": "Et si je préfère quand même me former ?"}, {"type": "p", "text": "Alors forme-toi. Dans trois cas précis, c''est le meilleur achat que tu puisses faire."}, {"type": "p", "text": "**Tu démarres et ton budget est serré.** Une formation à 90 € qui te donne les bases d''Instagram vaut mieux qu''un accompagnement à 2 000 € que tu financerais à crédit. On ne construit pas une communication sur de l''angoisse financière. (Si c''est ton cas, commence par [ma formation Instagram gratuite](/formation-gratuite-instagram) : elle ne te coûtera que ton temps.)"}, {"type": "p", "text": "**Tu veux internaliser durablement.** Si ta communication sera portée par toi pendant les dix prochaines années, apprendre pour de bon est rentable. Une formation solide, plus de la pratique, plus le temps."}, {"type": "p", "text": "**Tu appliques bien, seule.** Certaines personnes fonctionnent comme ça. Elles achètent une formation, la terminent, publient. Si c''est toi, tu n''as pas besoin de payer pour de l''accompagnement : tu as besoin d''un bon programme et de le suivre."}, {"type": "p", "text": "Le seul cas où je te déconseille la formation seule, c''est celui du **deuxième achat**. Si tu as déjà acheté une formation que tu n''as pas terminée, en acheter une autre ne réglera rien. Le problème n''était pas le contenu."}, {"type": "h2", "text": "Questions fréquentes"}, {"type": "h3", "text": "Une formation Instagram gratuite peut-elle suffire ?"}, {"type": "p", "text": "Pour comprendre le fonctionnement de la plateforme, oui. Les [ressources gratuites de Meta](https://www.facebook.com/business/learn) et les cours des créatrices sérieuses couvrent les bases — [ma propre formation Instagram](/formation-gratuite-instagram) est gratuite, elle aussi. Ce qu''elles ne peuvent pas faire, c''est regarder ton compte, ton offre et ton marché pour te dire ce qu''il faut publier, **toi**."}, {"type": "h3", "text": "Combien de temps faut-il pour voir des effets sur Instagram ?"}, {"type": "p", "text": "Compte trois à six mois de publication régulière avant que les chiffres bougent de façon lisible. Toute promesse de résultat en trente jours repose sur de la publicité, un compte déjà installé, ou rien du tout."}, {"type": "h3", "text": "Faut-il publier tous les jours ?"}, {"type": "p", "text": "Non. Une régularité que tu peux tenir bat une intensité que tu abandonnes en six semaines. Deux publications par semaine tenues un an valent mieux que sept par semaine tenues un mois."}, {"type": "h3", "text": "Quelle différence entre coaching, mentorat et accompagnement ?"}, {"type": "p", "text": "Le coaching travaille sur toi et tes blocages, sans forcément produire de livrable. Le mentorat te transmet l''expérience de quelqu''un qui a déjà fait le chemin. L''accompagnement de type faire-avec produit des livrables avec toi. Les trois mots sont utilisés indifféremment sur le marché, donc pose la question 1 ci-dessus plutôt que de te fier au terme."}, {"type": "h3", "text": "Peut-on financer un accompagnement en communication avec le CPF ?"}, {"type": "p", "text": "Seulement s''il est porté par un organisme de formation certifié Qualiopi et déclaré comme action de formation. Un accompagnement personnalisé sur mesure ne l''est généralement pas. Demande-le explicitement avant de signer, jamais après."}, {"type": "h3", "text": "Comment savoir si mon problème est le savoir ou le temps ?"}, {"type": "p", "text": "Réponds à ceci : si quelqu''un te donnait aujourd''hui ton plan de communication complet des six prochains mois, saurais-tu quoi publier lundi ? Si oui, ton problème est le temps et l''exécution, et une formation de plus n''y changera rien. Si non, une formation est encore utile."}, {"type": "h2", "text": "Par où commencer"}, {"type": "img", "src": "/blog/alternative-formation-instagram-3.webp", "alt": "Un carnet fermé, une plante et une tasse sur un rebord de fenêtre ensoleillé : commencer par ce qu''on ne veut plus faire seule"}, {"type": "p", "text": "Si tu te reconnais dans la frustration décrite au début de cet article, la question à te poser n''est pas « quelle formation choisir » mais « **qu''est-ce que je ne veux plus faire seule** »."}, {"type": "p", "text": "Chez Nowadays Agency, on en parle en appel découverte de 30 minutes, gratuit et sans engagement. On regarde ton compte, ton offre et là où tu bloques, et on te dit lequel des six formats te correspond, même quand ce n''est pas le nôtre."}, {"type": "button", "text": "Réserver un appel découverte", "href": "https://calendly.com/laetitia-mattioli/30-min-de-diagnostic-offert"}, {"type": "p", "text": "30 minutes, gratuites, sans engagement. Ou [écris-moi](/contact), si tu préfères l''écrit."}, {"type": "h3", "text": "Sources"}, {"type": "p", "text": "Prix des formations Instagram : [MaFormation](https://www.maformation.fr/actualites/prix-formation-instagram-187807), 23 février 2026\nTarifs LiveMentor 2026 : [Éloge de la curiosité](https://elogedelacuriosite.com/tous-sujets-curieux/formations/livementor-prix/), mis à jour le 11 mai 2026\nTJM et forfaits community manager freelance : [Plateya](https://www.plateya.fr/blog/detail/tarif-community-manager-freelance-grille-2026-tjm-forfaits-plateya), 10 mai 2026, d''après les données Malt 2026\nCoût d''un audit et de la gestion déléguée en agence : [Plateya](https://www.plateya.fr/blog/detail/cout-agence-reseaux-sociaux-guide-complet-des-tarifs-2026), 15 janvier 2026"}, {"type": "p", "text": "*Article publié sur Les Tracts, le blog de Nowadays Agency. Dernière mise à jour : août 2026.*"}]'::jsonb,
  'Alternative aux formations Instagram : 6 options',
  'Six alternatives aux formations Instagram en ligne : prix réels 2026, à qui chacune s''adresse, et les 4 questions à poser avant de signer.'
)
